func isFilteredForFailure(out string) bool {
	// returns true if should be filtered out (not shown in failure grouping)
	// For failure grouping, filter RUN, PAUSE, CONT, PASS, SKIP
	trim := strings.TrimLeft(out, " \t")
	if strings.HasPrefix(trim, "=== RUN") {
		return true
	}
	if strings.HasPrefix(trim, "=== PAUSE") {
		return true
	}
	if strings.HasPrefix(trim, "=== CONT") {
		return true
	}
	if strings.HasPrefix(trim, "--- PASS:") {
		return true
	}
	if strings.HasPrefix(trim, "--- SKIP:") {
		return true
	}
	// What about "--- PASS" with leading spaces but without colon? The go output is "--- PASS: Test (0.00s)" – includes colon. So filter prefix "--- PASS:" is sufficient.
	// Similarly SKIP.
	// Also filter "ok", "?", "FAIL\t"? For failure grouping, should we filter package summary lines? In earlier failure grouping for normal fail package, they did NOT include "ok" or "FAIL\t". So those should be filtered for failure grouping. But they are package-level outputs, not test-level. For test-level output, we only have test outputs, not package summaries. So package-level outputs like "ok" and "FAIL\t" are in pkg.Outputs, not t.Output. So we don't need to filter them for test failure grouping.
	// However test-level output could include "PASS\n" or "ok" ? No.
	// So keep everything else.
	return false
}

