func formatTimestamp(tStr string) string {
	// try parse with various layouts
	// go test uses RFC3339Nano
	layouts := []string{
		time.RFC3339Nano,
		time.RFC3339,
		"2006-01-02T15:04:05.999999999Z07:00",
		"2006-01-02T15:04:05Z07:00",
	}
	for _, l := range layouts {
		if tm, err := time.Parse(l, tStr); err == nil {
			// format as "2006-01-02T15:04:05Z" (UTC)
			return tm.UTC().Format("2006-01-02T15:04:05Z")
		}
	}
	// fallback: trim at 'Z' or to seconds
	// Try to find '.' and 'Z'
	// If contains '.', take up to 'Z' without fraction? Simple: if length >=20, take first 20 chars? But better return as is truncated to seconds
