func renderTestTableBasic(w io.Writer, tests []*Test, color bool, smallscreen bool) {
	// Compute widths
	// headers: Status, Elapsed, Test, Package
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	// Prepare display rows: each test expanded into lines
	type Row struct {
		Status  string
		Elapsed string
		TestLines []string // each line for test column
		Package string
		OriginalTest *Test
	}
	var rows []Row
	for _, t := range tests {
		status := t.Status
		elapsed := formatElapsedTest(t.Elapsed)
		// For status colors, we will apply later
		testLines := []string{t.Name}
		if smallscreen {
			testLines = splitTestNameSmallscreen(t.Name)
		}
		rows = append(rows, Row{
			Status:  status,
			Elapsed: elapsed,
			TestLines: testLines,
			Package: t.Package,
			OriginalTest: t,
		})
	}

	// Compute column widths (visible)
	// For Status: max of header and all statuses
	maxStatus := len(headers[0])
	maxElapsed := len(headers[1])
	maxTest := len(headers[2])
	maxPackage := len(headers[3])
	for _, r := range rows {
		if len(r.Status) > maxStatus {
			maxStatus = len(r.Status)
		}
		if len(r.Elapsed) > maxElapsed {
			maxElapsed = len(r.Elapsed)
		}
		for _, tl := range r.TestLines {
			if utf8.RuneCountInString(tl) > maxTest {
				maxTest = utf8.RuneCountInString(tl)
			}
		}
		if utf8.RuneCountInString(r.Package) > maxPackage {
			maxPackage = utf8.RuneCountInString(r.Package)
		}
	}
	// Add padding 2 for each column (one space each side) => width = maxContent +2? But need to include header?
	// Actually header length already counted, but we need width = maxContentLen +2? Let's compute:
	// For Status: header "Status" len6, maxStatus maybe 6, width = maxStatus+2 =8. That matches earlier.
	// For Elapsed: header 7, width 9.
	// For Test: header 4, but maxTest maybe longer, width = maxTest+2.
	// For Package: header 7, width = maxPackage+2? For pkg/a len5, maxPackage 5, width 7? But earlier width for pkg/a was 9, not 7. So header dominates.
	// So width = max(len(header), maxContent) +2

	widths := []int{
		maxInt(len(headers[0]), maxStatus) + 2,
		maxInt(len(headers[1]), maxElapsed) + 2,
		maxInt(len(headers[2]), maxTest) + 2,
		maxInt(len(headers[3]), maxPackage) + 2,
	}

	// Render top border
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")

	// Header row
	fmt.Fprint(w, "│")
	for i, h := range headers {
		padded := padCenter(h, widths[i])
		fmt.Fprint(w, padded)
		fmt.Fprint(w, "│")
	}
	fmt.Fprintln(w, "")

	// Separator
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")

	// Rows
	for _, r := range rows {
		// For each test line
