			// For width calculation we used visible length, but for padding we need visible length too.
			paddedStatus := padCenterVisible(statusCell, widths[0])
			fmt.Fprint(w, paddedStatus)
			fmt.Fprint(w, "│")

			// Elapsed column: only first line
			var elapsedCell string
			if lineIdx == 0 {
				elapsedCell = r.Elapsed
			} else {
				elapsedCell = ""
			}
			paddedElapsed := padCenter(elapsedCell, widths[1])
			fmt.Fprint(w, paddedElapsed)
			fmt.Fprint(w, "│")

			// Test column: left aligned
			paddedTest := padLeft(tLine, widths[2])
			fmt.Fprint(w, paddedTest)
			fmt.Fprint(w, "│")

			// Package column: only first line has package, others empty, left aligned
			var pkgCell string
			if lineIdx == 0 {
				pkgCell = r.Package
			} else {
