func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func padCenter(s string, width int) string {
	// count runes of s without ANSI? Assume s without ANSI for now.
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	totalPad := width - l
	left := totalPad / 2
	right := totalPad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padCenterVisible(s string, width int) string {
	// need to handle ANSI codes
	// strip ANSI for length
	visible := stripANSI(s)
	l := utf8.RuneCountInString(visible)
	if l >= width {
		return s
	}
	totalPad := width - l
	left := totalPad / 2
	right := totalPad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	// left 1 space, rest right
	// Actually left-aligned with 1 space left: format " " + s + spaces
	// But if width is larger than len(s)+1, we need to have 1 left + s + (width-1-len(s)) right
	if width-l-1 < 0 {
		return s
	}
	return " " + s + strings.Repeat(" ", width-1-l)
}

func stripANSI(s string) string {
	// remove \x1b[...m sequences
	re := regexp.MustCompile("\x1b\\[[0-9;]*m")
	return re.ReplaceAllString(s, "")
}

func colorStatus(s string) string {
	switch s {
	case "PASS":
		return "\x1b[92m" + s + "\x1b[0m"
	case "FAIL":
		return "\x1b[91m" + s + "\x1b[0m"
	case "SKIP":
		return "\x1b[93m" + s + "\x1b[0m"
	case "NOTEST":
		return "\x1b[93m" + s + "\x1b[0m"
	case "PANIC":
		return "\x1b[91m" + s + "\x1b[0m"
	default:
		return s
	}
}

func splitTestNameSmallscreen(name string) []string {
	// If len <=32 or no slash, return single
	if utf8.RuneCountInString(name) <= 32 || !strings.Contains(name, "/") {
		return []string{name}
	}
	parts := strings.Split(name, "/")
	var lines []string
	for i, part := range parts {
		if i == 0 {
			// first part
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, part)
			} else {
				// wrap first part
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, ch+" …")
						} else {
							lines = append(lines, ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "   "+ch+" …")
						} else {
							lines = append(lines, "   "+ch)
						}
					}
				}
			}
		} else {
			// subsequent parts with "  /" prefix
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, "  /"+part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, "  /"+ch+" …")
						} else {
							lines = append(lines, "  /"+ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "   "+ch+" …")
						} else {
							lines = append(lines, "   "+ch)
						}
					}
				}
			}
		}
	}
	return lines
}

func chunkString(s string, size int) []string {
	var chunks []string
	runes := []rune(s)
	for len(runes) > 0 {
		if len(runes) <= size {
			chunks = append(chunks, string(runes))
			break
		}
		chunks = append(chunks, string(runes[:size]))
		runes = runes[size:]
	}
	return chunks
}

