	// bottom
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}

