	}

	widths := make([]int, 3)
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}

	// Render header
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")

	// separator
	fmt.Fprint(w, "|")
	for i, wd := range widths {
		// markdown separator is dashes, length wd? Actually for markdown, separator is "--------" with dashes, not including spaces? In observed: "|--------|---------|---------|" – dashes length equals width? Let's see widths include padding, but separator is dashes only (no spaces). For width 8, separator "--------" (8 dashes). So use wd dashes.
		fmt.Fprint(w, strings.Repeat("-", wd))
		if i < len(widths)-1 {
			// Actually they have "|" between
		}
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")

	// rows
	for _, r := range rows {
		for lineIdx, tLine := range r.TestLines {
			fmt.Fprint(w, "|")
			var statusCell string
			if lineIdx == 0 {
				statusCell = r.Status
			}
			fmt.Fprint(w, padCenter(statusCell, widths[0]))
			fmt.Fprint(w, "|")
			var elapsedCell string
			if lineIdx == 0 {
				elapsedCell = r.Elapsed
			}
			fmt.Fprint(w, padCenter(elapsedCell, widths[1]))
			fmt.Fprint(w, "|")
			fmt.Fprint(w, padLeft(tLine, widths[2])) // actually test left?
			// For markdown, test column left aligned? In observed, test column had spaces around, but content left-aligned? For simplicity left.
			fmt.Fprint(w, "|")
			fmt.Fprintln(w, "")
		}
	}
}

func renderPackageTableMarkdown(w io.Writer, pkgs []*Package, color bool) {
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	maxVals := make([]int, len(headers))
	for i, h := range headers {
		maxVals[i] = len(h)
	}
	type RowLines struct {
		Lines [][]string
	}
	var allRows []RowLines
	for _, pkg := range pkgs {
		status := pkg.Status
		if color {
			switch status {
			case "PASS":
				status = "🟢 PASS"
			case "FAIL":
				status = "🔴 FAIL"
			case "SKIP":
				status = "🟡 SKIP"
			case "NOTEST":
				status = "🟡 NOTEST"
			case "PANIC":
				status = "🔴 PANIC"
			}
		}
		elapsed := pkg.ElapsedStr
		pkgName := pkg.OrigName
		if pkgName == "__empty__" {
			pkgName = ""
		}
		cover := pkg.Cover
		var passStr, failStr, skipStr string
		if pkg.IsNoTest {
			passStr = "--"
			failStr = "--"
			skipStr = "--"
		} else {
			passStr = strconv.Itoa(pkg.PassCount)
			failStr = strconv.Itoa(pkg.FailCount)
			skipStr = strconv.Itoa(pkg.SkipCount)
		}

		if pkg.IsNoTest {
			line1 := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			line2 := []string{"", "", pkg.NoTestMessage, "", "", "", ""}
			allRows = append(allRows, RowLines{Lines: [][]string{line1, line2}})
			for i, cell := range line1 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
			for i, cell := range line2 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		} else {
			line := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			allRows = append(allRows, RowLines{Lines: [][]string{line}})
			for i, cell := range line {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		}
	}
	widths := make([]int, len(headers))
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}

	// header
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")

	// separator
	fmt.Fprint(w, "|")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("-", wd))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")

	for _, rl := range allRows {
		for _, line := range rl.Lines {
			fmt.Fprint(w, "|")
			for i, cell := range line {
				var padded string
				if i == 2 {
					padded = padLeft(cell, widths[i])
				} else {
					padded = padCenter(cell, widths[i])
				}
				fmt.Fprint(w, padded)
				fmt.Fprint(w, "|")
			}
			fmt.Fprintln(w, "")
		}
	}
	fmt.Fprintln(w, "")
}

