			break
		}
	}
	var finalPkgList []*Package
	for _, p := range pkgList {
		if p.IsNoTest {
			if flagNoTests || !hasNonNoTest {
				finalPkgList = append(finalPkgList, p)
			}
		} else {
			// For package-level skip without IsNoTest and with empty name, original still shows? In our earlier, "only pkg skip" case finalPkgList includes it even though Name empty. So include.
			finalPkgList = append(finalPkgList, p)
		}
	}
	switch flagSort {
	case "name":
		sort.Slice(finalPkgList, func(i, j int) bool { return finalPkgList[i].Name < finalPkgList[j].Name })
	case "elapsed":
		sort.Slice(finalPkgList, func(i, j int) bool {
			if finalPkgList[i].Elapsed != finalPkgList[j].Elapsed {
				return finalPkgList[i].Elapsed > finalPkgList[j].Elapsed
			}
			return finalPkgList[i].Name < finalPkgList[j].Name
		})
	case "cover":
		sort.Slice(finalPkgList, func(i, j int) bool {
			if finalPkgList[i].CoverPct != finalPkgList[j].CoverPct {
				return finalPkgList[i].CoverPct > finalPkgList[j].CoverPct
			}
			return finalPkgList[i].Name < finalPkgList[j].Name
		})
	}
	exitCode := 0
	for _, p := range finalPkgList {
		if p.Status == "FAIL" || p.Status == "PANIC" {
			exitCode = 1
			break
		}
	}
	switch flagFormat {
	case "basic":
		renderBasic(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	case "plain":
		renderPlain(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	case "markdown":
		renderMarkdown(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	}
	os.Exit(exitCode)
}

// helpers
func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
func padCenter(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}
func padCenterVisible(s string, width int) string {
	vis := stripANSI(s)
	l := utf8.RuneCountInString(vis)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}
func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return " " + s + strings.Repeat(" ", width-1-l)
}
func stripANSI(s string) string {
	re := regexp.MustCompile("\x1b\\[[0-9;]*m")
	return re.ReplaceAllString(s, "")
}
func colorStatus(s string) string {
	switch s {
	case "PASS":
		return "\x1b[92m" + s + "\x1b[0m"
	case "FAIL":
		return "\x1b[91m" + s + "\x1b[0m"
	case "SKIP":
		return "\x1b[93m" + s + "\x1b[0m"
	case "NOTEST":
		return "\x1b[93m" + s + "\x1b[0m"
	case "PANIC":
		return "\x1b[91m" + s + "\x1b[0m"
	default:
		return s
	}
}
func splitTestNameSmallscreen(name string) []string {
	if utf8.RuneCountInString(name) <= 32 || !strings.Contains(name, "/") {
		return []string{name}
	}
	parts := strings.Split(name, "/")
	var lines []string
	for i, part := range parts {
		if i == 0 {
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, ch+" …")
						} else {
							lines = append(lines, ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "   "+ch+" …")
						} else {
							lines = append(lines, "   "+ch)
						}
					}
				}
			}
		} else {
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, "  /"+part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, "  /"+ch+" …")
						} else {
							lines = append(lines, "  /"+ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "   "+ch+" …")
						} else {
							lines = append(lines, "   "+ch)
						}
					}
				}
			}
		}
	}
	return lines
}
func chunkString(s string, size int) []string {
	var chunks []string
	runes := []rune(s)
	for len(runes) > 0 {
		if len(runes) <= size {
			chunks = append(chunks, string(runes))
			break
		}
		chunks = append(chunks, string(runes[:size]))
		runes = runes[size:]
	}
	return chunks
}
func renderBasic(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
	if showTest && len(tests) > 0 {
		renderTestTableBasic(w, tests, color, smallscreen)
	}
	for _, pkg := range pkgs {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			renderFailureGrouping(w, pkg, color)
		}
	}
	if len(pkgs) > 0 {
		renderPackageTableBasic(w, pkgs, color)
	}
}
func renderPlain(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
	if showTest && len(tests) > 0 {
		renderTestTableBasic(w, tests, color, smallscreen) // placeholder use basic for now
	}
	for _, pkg := range pkgs {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			renderFailureGrouping(w, pkg, color)
		}
	}
	if len(pkgs) > 0 {
		renderPackageTableBasic(w, pkgs, color)
	}
}
func renderMarkdown(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
	grouped := make(map[string][]*Test)
	for _, t := range tests {
		grouped[t.Package] = append(grouped[t.Package], t)
	}
	if showTest {
		for _, pkg := range pkgs {
			ts, ok := grouped[pkg.Name]
			if !ok || len(ts) == 0 {
				continue
			}
			sort.Slice(ts, func(i, j int) bool { return ts[i].Name < ts[j].Name })
			orig := pkg.OrigName
			if orig == "" {
				orig = pkg.Name
			}
			if orig == "__empty__" {
				orig = ""
			}
			fmt.Fprintf(w, "## 📦 Package `%s`\n\n", orig)
			fmt.Fprintf(w, "Tests: ✓ %d passed | %d skipped | %d failed\n\n", pkg.PassCount, pkg.SkipCount, pkg.FailCount)
			fmt.Fprintln(w, "<details>")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "<summary>Click for test summary</summary>")
			fmt.Fprintln(w, "")
			renderTestTableMarkdownInner(w, ts, color, smallscreen)
			fmt.Fprintln(w, "</details>")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "")
		}
	}
	for _, pkg := range pkgs {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			if pkg.HasPanic && pkg.PanicTest != nil {
				if color {
					fmt.Fprintf(w, "## 🔴 PANIC • %s • %s\n\n", pkg.OrigName, pkg.PanicTest.Name)
				} else {
					fmt.Fprintf(w, "## PANIC • %s • %s\n\n", pkg.OrigName, pkg.PanicTest.Name)
				}
			} else {
				if color {
					fmt.Fprintf(w, "## 🔴 FAIL • %s\n\n", pkg.OrigName)
				} else {
					fmt.Fprintf(w, "## FAIL • %s\n\n", pkg.OrigName)
				}
			}
			fmt.Fprintln(w, "```")
			fmt.Fprintln(w, "")
			var failOutputs []string
			for _, t := range pkg.FailedTests {
				for _, out := range t.Output {
					if isFilteredForFailure(out) {
						continue
					}
					failOutputs = append(failOutputs, out)
				}
			}
			if len(failOutputs) > 0 {
				for _, o := range failOutputs {
					fmt.Fprint(w, o)
					if !strings.HasSuffix(o, "\n") {
						fmt.Fprintln(w)
					}
				}
			}
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "```")
			fmt.Fprintln(w, "")
		}
	}
	if len(pkgs) > 0 {
		renderPackageTableMarkdown(w, pkgs, color)
	}
}
func isFilteredForFailure(out string) bool {
	trim := strings.TrimLeft(out, " \t")
	if strings.HasPrefix(trim, "=== RUN") || strings.HasPrefix(trim, "=== PAUSE") || strings.HasPrefix(trim, "=== CONT") || strings.HasPrefix(trim, "--- PASS:") || strings.HasPrefix(trim, "--- SKIP:") {
		return true
	}
	return false
}
func renderFailureGrouping(w io.Writer, pkg *Package, color bool) {
	if pkg.Status == "PANIC" {
		var headerText string
		if pkg.PanicTest != nil {
			headerText = fmt.Sprintf("   PANIC  package: %s • %s   ", pkg.OrigName, pkg.PanicTest.Name)
		} else {
			headerText = fmt.Sprintf("   PANIC  package: %s   ", pkg.OrigName)
		}
		width := utf8.RuneCountInString(headerText)
		top := "┏" + strings.Repeat("━", width) + "┓"
		mid := "┃" + headerText + "┃"
		bottom := "┗" + strings.Repeat("━", width) + "┛"
		if color {
			top = "\x1b[38;5;103m" + top + "\x1b[0m"
			mid = "\x1b[38;5;103m┃\x1b[0m" + headerText + "\x1b[38;5;103m┃\x1b[0m"
			bottom = "\x1b[38;5;103m" + bottom + "\x1b[0m"
		}
		fmt.Fprintln(w, top)
		fmt.Fprintln(w, mid)
		fmt.Fprintln(w, bottom)
		fmt.Fprintln(w, "")
		if pkg.PanicTest != nil {
			for _, out := range pkg.PanicTest.Output {
				fmt.Fprint(w, out)
			}
		} else {
			for _, out := range pkg.Outputs {
				fmt.Fprint(w, out)
			}
		}
		fmt.Fprintln(w, "")
		return
	}
	if len(pkg.FailedTests) == 0 {
		return
	}
	headerText := fmt.Sprintf("   FAIL  package: %s   ", pkg.OrigName)
	width := utf8.RuneCountInString(headerText)
	top := "┏" + strings.Repeat("━", width) + "┓"
	mid := "┃" + headerText + "┃"
	bottom := "┗" + strings.Repeat("━", width) + "┛"
	if color {
		top = "\x1b[38;5;103m" + top + "\x1b[0m"
		mid = "\x1b[38;5;103m┃\x1b[0m   \x1b[91m\x1b[91mFAIL\x1b[0m\x1b[0m  package: " + pkg.OrigName + "   \x1b[38;5;103m┃\x1b[0m"
		bottom = "\x1b[38;5;103m" + bottom + "\x1b[0m"
	}
	fmt.Fprintln(w, top)
	fmt.Fprintln(w, mid)
	fmt.Fprintln(w, bottom)
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "")
	for idx, t := range pkg.FailedTests {
		if idx > 0 {
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, strings.Repeat("─", 128))
			fmt.Fprintln(w, strings.Repeat(" ", 128))
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "")
		}
		for _, out := range t.Output {
			if isFilteredForFailure(out) {
				continue
			}
			fmt.Fprint(w, out)
			if !strings.HasSuffix(out, "\n") {
				fmt.Fprintln(w)
			}
		}
	}
	fmt.Fprintln(w, "")
}
func renderTestTableBasic(w io.Writer, tests []*Test, color bool, smallscreen bool) {
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	type Row struct {
		Status      string
		Elapsed     string
		TestLines   []string
		Package     string
		Orig        *Test
	}
	var rows []Row
	for _, t := range tests {
		rows = append(rows, Row{
			Status:    t.Status,
			Elapsed:   formatElapsedTest(t.Elapsed),
			TestLines: splitTestNameSmallscreen(t.Name),
			Package:   t.Package,
			Orig:      t,
		})
	}
	maxVals := []int{len(headers[0]), len(headers[1]), len(headers[2]), len(headers[3])}
	for _, r := range rows {
		if len(r.Status) > maxVals[0] {
			maxVals[0] = len(r.Status)
		}
		if len(r.Elapsed) > maxVals[1] {
			maxVals[1] = len(r.Elapsed)
		}
		for _, tl := range r.TestLines {
			if utf8.RuneCountInString(tl) > maxVals[2] {
				maxVals[2] = utf8.RuneCountInString(tl)
			}
		}
		if utf8.RuneCountInString(r.Package) > maxVals[3] {
			maxVals[3] = utf8.RuneCountInString(r.Package)
		}
	}
	widths := make([]int, 4)
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")
	fmt.Fprint(w, "│")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "│")
	}
	fmt.Fprintln(w, "")
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")
	for _, r := range rows {
		for lineIdx, tLine := range r.TestLines {
			fmt.Fprint(w, "│")
			var statusCell string
			if lineIdx == 0 {
				statusCell = r.Status
			}
			if color && statusCell != "" {
				statusCell = colorStatus(statusCell)
			}
			fmt.Fprint(w, padCenterVisible(statusCell, widths[0]))
			fmt.Fprint(w, "│")
			var elapsedCell string
			if lineIdx == 0 {
				elapsedCell = r.Elapsed
			}
			fmt.Fprint(w, padCenter(elapsedCell, widths[1]))
			fmt.Fprint(w, "│")
			fmt.Fprint(w, padLeft(tLine, widths[2]))
			fmt.Fprint(w, "│")
			var pkgCell string
			if lineIdx == 0 {
				pkgCell = r.Package
			}
			fmt.Fprint(w, padLeft(pkgCell, widths[3]))
			fmt.Fprint(w, "│")
			fmt.Fprintln(w, "")
		}
	}
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}
func renderPackageTableBasic(w io.Writer, pkgs []*Package, color bool) {
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	maxVals := make([]int, len(headers))
	for i, h := range headers {
		maxVals[i] = len(h)
	}
	type RowLines struct{ Lines [][]string }
	var allRows []RowLines
	for _, pkg := range pkgs {
		status := pkg.Status
		elapsed := pkg.ElapsedStr
		pkgName := pkg.Name
		cover := pkg.Cover
		var passStr, failStr, skipStr string
		if pkg.IsNoTest {
			passStr = "--"
			failStr = "--"
			skipStr = "--"
		} else {
			passStr = strconv.Itoa(pkg.PassCount)
			failStr = strconv.Itoa(pkg.FailCount)
			skipStr = strconv.Itoa(pkg.SkipCount)
		}
		if pkg.IsNoTest {
			line1 := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			line2 := []string{"", "", pkg.NoTestMessage, "", "", "", ""}
			allRows = append(allRows, RowLines{Lines: [][]string{line1, line2}})
			for i, cell := range line1 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
			for i, cell := range line2 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		} else {
			line := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			allRows = append(allRows, RowLines{Lines: [][]string{line}})
			for i, cell := range line {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		}
	}
	widths := make([]int, len(headers))
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")
	fmt.Fprint(w, "│")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "│")
	}
	fmt.Fprintln(w, "")
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")
	for _, rl := range allRows {
		for _, line := range rl.Lines {
			fmt.Fprint(w, "│")
			for i, cell := range line {
				var padded string
				if i == 2 {
					padded = padLeft(cell, widths[i])
				} else {
					if i == 0 && color && cell != "" {
						padded = padCenterVisible(colorStatus(cell), widths[i])
					} else {
						padded = padCenter(cell, widths[i])
					}
				}
				fmt.Fprint(w, padded)
				fmt.Fprint(w, "│")
			}
			fmt.Fprintln(w, "")
		}
	}
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}
func renderTestTableMarkdownInner(w io.Writer, tests []*Test, color bool, smallscreen bool) {
	headers := []string{"Status", "Elapsed", "Test"}
	type Row struct {
		Status    string
		Elapsed   string
		TestLines []string
	}
	var rows []Row
	maxVals := []int{len(headers[0]), len(headers[1]), len(headers[2])}
	for _, t := range tests {
		status := t.Status
		if color {
			switch status {
			case "PASS":
				status = "🟢 PASS"
			case "FAIL":
				status = "🔴 FAIL"
			case "SKIP":
				status = "🟡 SKIP"
			case "NOTEST":
				status = "🟡 NOTEST"
			case "PANIC":
				status = "🔴 PANIC"
			}
		}
		elapsed := formatElapsedTest(t.Elapsed)
		testLines := splitTestNameSmallscreen(t.Name)
		rows = append(rows, Row{Status: status, Elapsed: elapsed, TestLines: testLines})
		if utf8.RuneCountInString(status) > maxVals[0] {
			maxVals[0] = utf8.RuneCountInString(status)
		}
		if utf8.RuneCountInString(elapsed) > maxVals[1] {
			maxVals[1] = utf8.RuneCountInString(elapsed)
		}
		for _, tl := range testLines {
			if utf8.RuneCountInString(tl) > maxVals[2] {
				maxVals[2] = utf8.RuneCountInString(tl)
			}
		}
	}
	widths := make([]int, 3)
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")
	fmt.Fprint(w, "|")
	for _, wd := range widths {
		fmt.Fprint(w, strings.Repeat("-", wd))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")
	for _, r := range rows {
		for lineIdx, tLine := range r.TestLines {
			fmt.Fprint(w, "|")
			var statusCell string
			if lineIdx == 0 {
				statusCell = r.Status
			}
			fmt.Fprint(w, padCenter(statusCell, widths[0]))
			fmt.Fprint(w, "|")
			var elapsedCell string
			if lineIdx == 0 {
				elapsedCell = r.Elapsed
			}
			fmt.Fprint(w, padCenter(elapsedCell, widths[1]))
			fmt.Fprint(w, "|")
			fmt.Fprint(w, padLeft(tLine, widths[2]))
			fmt.Fprint(w, "|")
			fmt.Fprintln(w, "")
		}
	}
}
