		var passStr, failStr, skipStr string
		if pkg.IsNoTest {
			passStr = "--"
			failStr = "--"
			skipStr = "--"
		} else {
			passStr = strconv.Itoa(pkg.PassCount)
			failStr = strconv.Itoa(pkg.FailCount)
			skipStr = strconv.Itoa(pkg.SkipCount)
		}
		if pkg.IsNoTest {
			line1 := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			line2 := []string{"", "", pkg.NoTestMessage, "", "", "", ""}
			allRows = append(allRows, RowLines{Lines: [][]string{line1, line2}})
			for i, cell := range line1 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
			for i, cell := range line2 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		} else {
			line := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			allRows = append(allRows, RowLines{Lines: [][]string{line}})
			for i, cell := range line {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		}
	}
	widths := make([]int, len(headers))
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	fmt.Fprint(w, "|")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")
	fmt.Fprint(w, "|")
	for _, wd := range widths {
		fmt.Fprint(w, strings.Repeat("-", wd))
		fmt.Fprint(w, "|")
	}
	fmt.Fprintln(w, "")
	for _, rl := range allRows {
		for _, line := range rl.Lines {
			fmt.Fprint(w, "|")
			for i, cell := range line {
				var padded string
				if i == 2 {
					padded = padLeft(cell, widths[i])
				} else {
					padded = padCenter(cell, widths[i])
				}
				fmt.Fprint(w, padded)
				fmt.Fprint(w, "|")
			}
			fmt.Fprintln(w, "")
		}
	}
	fmt.Fprintln(w, "")
}
