cat <<'GO' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

type Event struct {
	Time    string  `json:"Time"`
	Action  string  `json:"Action"`
	Package string  `json:"Package"`
	Test    string  `json:"Test"`
	Output  string  `json:"Output"`
	Elapsed float64 `json:"Elapsed"`
}

type Test struct {
	Name        string
	Package     string
	OrigPackage string
	Elapsed     float64
	Status      string
	Output      []string
	IsPanic     bool
	SortCover   float64
	Index       int
}

type Package struct {
	OrigName         string
	TrimmedName      string
	Name             string
	Elapsed          float64
	ElapsedStr       string
	ElapsedIsCached  bool
	Cover            string
	CoverPct         float64
	Status           string
	PassCount        int
	FailCount        int
	SkipCount        int
	Tests            map[string]*Test
	Outputs          []string
	FailedTests      []*Test
	IsNoTest         bool
	NoTestMessage    string
	HasPanic         bool
	PanicTest        *Test
	PkgSkipCount     int
}

func formatElapsedPackage(f float64, isCached bool) string {
	if isCached {
		return "(cached)"
	}
	return fmt.Sprintf("%.2fs", f)
}
func formatElapsedTest(f float64) string {
	return fmt.Sprintf("%.2f", f)
}
func formatTimestamp(tStr string) string {
	for _, l := range []string{time.RFC3339Nano, time.RFC3339} {
		if tm, err := time.Parse(l, tStr); err == nil {
			return tm.UTC().Format("2006-01-02T15:04:05Z")
		}
	}
	if idx := strings.Index(tStr, "."); idx != -1 {
		return tStr[:idx] + "Z"
	}
	return tStr
}

func main() {
	var (
		showHelp         bool
		showVersion      bool
		flagAll          bool
		flagPass         bool
		flagSkip         bool
		flagNoTests      bool
		flagSmallScreen  bool
		flagSlow         int
		flagSort         string
		flagNoColor      bool
		flagFormat       string
		flagFile         string
		flagFollow       bool
		flagFollowOutput string
		flagIncludeTS    bool
		flagProgress     bool
		flagCompare      string
		flagTrimPath     string
	)
	flag.BoolVar(&showHelp, "h", false, "")
	flag.BoolVar(&showVersion, "v", false, "")
	flag.BoolVar(&flagAll, "all", false, "")
	flag.BoolVar(&flagPass, "pass", false, "")
	flag.BoolVar(&flagSkip, "skip", false, "")
	flag.BoolVar(&flagNoTests, "notests", false, "")
	flag.BoolVar(&flagSmallScreen, "smallscreen", false, "")
	flag.IntVar(&flagSlow, "slow", 0, "")
	flag.StringVar(&flagSort, "sort", "name", "")
	flag.BoolVar(&flagNoColor, "nocolor", false, "")
	flag.StringVar(&flagFormat, "format", "basic", "")
	flag.StringVar(&flagFile, "file", "", "")
	flag.BoolVar(&flagFollow, "follow", false, "")
	flag.StringVar(&flagFollowOutput, "follow-output", "", "")
	flag.BoolVar(&flagIncludeTS, "include-timestamp", false, "")
	flag.BoolVar(&flagProgress, "progress", false, "")
	flag.StringVar(&flagCompare, "compare", "", "")
	flag.StringVar(&flagTrimPath, "trimpath", "", "")
	flag.Usage = func() {
		fmt.Fprint(os.Stdout, "Usage:\n    go test ./... -json | tparse [options...]\n    go test [packages...] -json | tparse [options...]\n    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out\n\nOptions:\n    -h                 Show help.\n    -v                 Show version.\n    -all               Display table event for pass and skip. (Failed items always displayed)\n    -pass              Display table for passed tests.\n    -skip              Display table for skipped tests.\n    -notests           Display packages containing no test files or empty test files.\n    -smallscreen       Split subtest names vertically to fit on smaller screens.\n    -slow              Number of slowest tests to display. Default is 0, display all.\n    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.\n    -nocolor           Disable all colors. (NO_COLOR also supported)\n    -format            The output format for tables [basic, plain, markdown]. Default is basic.\n    -file              Read test output from a file.\n    -follow            Follow raw output from go test to stdout.\n    -follow-output     Write raw output from go test to a file (takes precedence over -follow).\n    -include-timestamp Include timestamps in follow output. \n    -progress          Print a single summary line for each package. Useful for long running test suites.\n    -compare           Compare against a previous test output file. (experimental)\n    -trimpath          Remove path prefix from package names in output, simplifying their display.\n")
	}
	flag.Parse()
	if showHelp {
		flag.Usage()
		return
	}
	if showVersion {
		fmt.Fprintln(os.Stdout, "tparse version: (devel)")
		return
	}
	if flagSort != "name" && flagSort != "elapsed" && flagSort != "cover" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -sort flag must be one of: name, elapsed or cover\n", flagSort)
		return
	}
	if flagFormat != "basic" && flagFormat != "plain" && flagFormat != "markdown" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -format flag must be one of: basic, plain or markdown\n", flagFormat)
		return
	}
	colorEnabled := true
	if flagNoColor {
		colorEnabled = false
	}
	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		colorEnabled = false
	}
	var reader io.Reader
	if flagFile != "" {
		f, err := os.Open(flagFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "open %s: %s\n", flagFile, err.Error())
			os.Exit(1)
		}
		defer f.Close()
		reader = f
	} else {
		fi, err := os.Stdin.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		reader = os.Stdin
	}
	var followFile *os.File
	if flagFollowOutput != "" {
		f, err := os.Create(flagFollowOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to create follow output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		followFile = f
	}
	if flagCompare != "" {
		if _, err := os.Open(flagCompare); err != nil {
			fmt.Fprintf(os.Stderr, "open %s: %s\n", flagCompare, err.Error())
			os.Exit(1)
		}
	}
	coverPctRe := regexp.MustCompile(`coverage:\s*([0-9.]+)%`)
	noTestFilesStr := "[no test files]"
	filterRunRe := regexp.MustCompile(`^\s*=== RUN`)
	filterPauseRe := regexp.MustCompile(`^\s*=== PAUSE`)
	filterContRe := regexp.MustCompile(`^\s*=== CONT`)
	filterPassRe := regexp.MustCompile(`^\s*--- PASS:`)
	filterSkipRe := regexp.MustCompile(`^\s*--- SKIP:`)

	type Completion struct {
		Package         string
		Status          string
		Elapsed         float64
		ElapsedStr      string
		ElapsedIsCached bool
		IsNoTest        bool
	}
	packages := make(map[string]*Package)
	pkgOrder := []string{}
	completionOrder := []Completion{}
	hasParsable := false
	scanner := bufio.NewScanner(reader)
	buf := make([]byte, 0, 1024*1024)
	scanner.Buffer(buf, 10*1024*1024)
	testIndex := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var ev Event
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			continue
		}
		hasParsable = true
		trimmedPkg := ev.Package
		if flagTrimPath != "" && strings.HasPrefix(ev.Package, flagTrimPath) {
			trimmedPkg = strings.TrimPrefix(ev.Package, flagTrimPath)
		}
		displayPkg := trimmedPkg
		if flagSmallScreen && displayPkg != "" {
			parts := strings.Split(displayPkg, "/")
			last := ""
			for i := len(parts) - 1; i >= 0; i-- {
				if parts[i] != "" {
					last = parts[i]
					break
				}
			}
			if last != "" {
				displayPkg = last
			}
		}
		origKey := ev.Package
		if origKey == "" {
			if displayPkg != "" {
				origKey = displayPkg
			} else {
				origKey = "__empty__"
			}
		}
		pkg, ok := packages[origKey]
		if !ok {
			pkg = &Package{
				OrigName:    ev.Package,
				TrimmedName: trimmedPkg,
				Name:        displayPkg,
				Tests:       make(map[string]*Test),
				Cover:       "--",
			}
			packages[origKey] = pkg
			pkgOrder = append(pkgOrder, origKey)
		}
		if ev.Action == "output" {
			if strings.Contains(ev.Output, "coverage:") {
				m := coverPctRe.FindStringSubmatch(ev.Output)
				if len(m) >= 2 {
					pkg.Cover = m[1] + "%"
					if f, err := strconv.ParseFloat(m[1], 64); err == nil {
						pkg.CoverPct = f
					}
				}
			}
			if strings.Contains(ev.Output, noTestFilesStr) {
				pkg.IsNoTest = true
				pkg.NoTestMessage = noTestFilesStr
				pkg.Status = "NOTEST"
			}
			if strings.Contains(ev.Output, "(cached)") {
				pkg.ElapsedIsCached = true
				pkg.ElapsedStr = "(cached)"
			}
			shouldFilter := false
			if filterRunRe.MatchString(ev.Output) || filterPauseRe.MatchString(ev.Output) || filterContRe.MatchString(ev.Output) || filterPassRe.MatchString(ev.Output) || filterSkipRe.MatchString(ev.Output) {
				shouldFilter = true
			}
			if !shouldFilter {
				followStr := ev.Output
				if flagIncludeTS {
					followStr = formatTimestamp(ev.Time) + " " + followStr
				}
				if followFile != nil {
					_, _ = followFile.WriteString(followStr)
				} else if flagFollow {
					fmt.Fprint(os.Stdout, followStr)
				}
			}
			if ev.Test != "" {
				t, exists := pkg.Tests[ev.Test]
				if !exists {
					t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
					testIndex++
					pkg.Tests[ev.Test] = t
				}
				t.Output = append(t.Output, ev.Output)
				if strings.Contains(ev.Output, "panic:") {
					t.IsPanic = true
					pkg.HasPanic = true
					if pkg.PanicTest == nil {
						pkg.PanicTest = t
					}
				}
			} else {
				pkg.Outputs = append(pkg.Outputs, ev.Output)
				if strings.Contains(ev.Output, "panic:") {
					pkg.HasPanic = true
				}
			}
			continue
		}
		switch ev.Action {
		case "run":
			t, exists := pkg.Tests[ev.Test]
			if !exists {
				t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
				testIndex++
				pkg.Tests[ev.Test] = t
			}
			t.Package = displayPkg
		case "pass", "fail", "skip":
			if ev.Test != "" {
				t, exists := pkg.Tests[ev.Test]
				if !exists {
					t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
					testIndex++
					pkg.Tests[ev.Test] = t
				}
				t.Status = strings.ToUpper(ev.Action)
				t.Elapsed = ev.Elapsed
				t.Package = displayPkg
			} else {
				pkg.Elapsed = ev.Elapsed
				if !pkg.ElapsedIsCached {
					if pkg.IsNoTest {
						pkg.Status = "NOTEST"
					} else {
						switch ev.Action {
						case "pass":
							pkg.Status = "PASS"
						case "fail":
							pkg.Status = "FAIL"
						case "skip":
							if pkg.IsNoTest {
								pkg.Status = "NOTEST"
							} else {
								pkg.Status = ""
								pkg.PkgSkipCount++
							}
						}
					}
				} else {
					if pkg.Status == "" || pkg.Status == "PASS" {
						pkg.Status = "PASS"
					}
				}
				if pkg.HasPanic {
					pkg.Status = "PANIC"
				}
				comp := Completion{Package: ev.Package, Status: pkg.Status, Elapsed: pkg.Elapsed, ElapsedStr: pkg.ElapsedStr, ElapsedIsCached: pkg.ElapsedIsCached, IsNoTest: pkg.IsNoTest}
				if comp.ElapsedStr == "" {
					if comp.ElapsedIsCached {
						comp.ElapsedStr = "(cached)"
					} else {
						comp.ElapsedStr = formatElapsedPackage(comp.Elapsed, false)
					}
				}
				if comp.Status == "" {
					comp.Status = strings.ToUpper(ev.Action)
				}
				completionOrder = append(completionOrder, comp)
			}
		}
	}
	if !hasParsable {
		fmt.Fprintln(os.Stderr, "no parsable events: Make sure to run go test with -json flag")
		os.Exit(1)
	}
	for _, key := range pkgOrder {
		pkg := packages[key]
		pass, fail, skip := 0, 0, 0
		for _, t := range pkg.Tests {
			switch t.Status {
			case "PASS":
				pass++
			case "FAIL":
				fail++
			case "SKIP":
				skip++
			}
		}
		pkg.PassCount = pass
		pkg.FailCount = fail
		pkg.SkipCount = skip + pkg.PkgSkipCount
		if pkg.ElapsedStr == "" {
			if pkg.ElapsedIsCached {
				pkg.ElapsedStr = "(cached)"
			} else {
				pkg.ElapsedStr = formatElapsedPackage(pkg.Elapsed, false)
			}
		}
		trimmed := pkg.OrigName
		if flagTrimPath != "" && strings.HasPrefix(pkg.OrigName, flagTrimPath) {
			trimmed = strings.TrimPrefix(pkg.OrigName, flagTrimPath)
		}
		pkg.TrimmedName = trimmed
		display := trimmed
		if flagSmallScreen && display != "" {
			parts := strings.Split(display, "/")
			last := ""
			for i := len(parts) - 1; i >= 0; i-- {
				if parts[i] != "" {
					last = parts[i]
					break
				}
			}
			if last != "" {
				display = last
			}
		}
		pkg.Name = display
		for _, t := range pkg.Tests {
			t.Package = pkg.Name
			t.SortCover = pkg.CoverPct
		}
		var failed []*Test
		for _, t := range pkg.Tests {
			if t.Status == "FAIL" || t.IsPanic {
				failed = append(failed, t)
			}
		}
		sort.Slice(failed, func(i, j int) bool { return failed[i].Name < failed[j].Name })
		pkg.FailedTests = failed
	}
	if flagProgress {
		for _, comp := range completionOrder {
			status := comp.Status
			if status == "" {
				status = "SKIP"
			}
			elapsedStr := comp.ElapsedStr
			if elapsedStr == "" {
				if comp.ElapsedIsCached {
					elapsedStr = "(cached)"
				} else {
					elapsedStr = formatElapsedPackage(comp.Elapsed, false)
				}
			}
			fmt.Fprintf(os.Stdout, "[%s]\t%10s\t%s\n", status, elapsedStr, comp.Package)
		}
	}
	showTestTable := flagAll || flagPass || flagSkip
	var allTests []*Test
	for _, key := range pkgOrder {
		for _, t := range packages[key].Tests {
			allTests = append(allTests, t)
		}
	}
	var filteredTests []*Test
	for _, t := range allTests {
		if !showTestTable {
			continue
		}
		include := false
		if flagAll {
			include = true
		} else {
			if t.Status == "FAIL" {
				include = true
			} else if t.Status == "PASS" && flagPass {
				include = true
			} else if t.Status == "SKIP" && flagSkip {
				include = true
			} else if t.Status == "" && (flagSkip || flagAll) {
				include = true
			}
		}
		if include {
			filteredTests = append(filteredTests, t)
		}
	}
	if flagSlow > 0 {
		var passes []*Test
		var others []*Test
		for _, t := range filteredTests {
			if t.Status == "PASS" {
				passes = append(passes, t)
			} else {
				others = append(others, t)
			}
		}
		sort.Slice(passes, func(i, j int) bool { return passes[i].Elapsed > passes[j].Elapsed })
		if len(passes) > flagSlow {
			passes = passes[:flagSlow]
		}
		filteredTests = append(passes, others...)
	}
	switch flagSort {
	case "name":
		sort.Slice(filteredTests, func(i, j int) bool {
			if filteredTests[i].Name != filteredTests[j].Name {
				return filteredTests[i].Name < filteredTests[j].Name
			}
			return filteredTests[i].Package < filteredTests[j].Package
		})
	case "elapsed":
		sort.Slice(filteredTests, func(i, j int) bool {
			if filteredTests[i].Elapsed != filteredTests[j].Elapsed {
				return filteredTests[i].Elapsed > filteredTests[j].Elapsed
			}
			return filteredTests[i].Name < filteredTests[j].Name
		})
	case "cover":
		sort.Slice(filteredTests, func(i, j int) bool {
			if filteredTests[i].SortCover != filteredTests[j].SortCover {
				return filteredTests[i].SortCover > filteredTests[j].SortCover
			}
			if filteredTests[i].Elapsed != filteredTests[j].Elapsed {
				return filteredTests[i].Elapsed > filteredTests[j].Elapsed
			}
			return filteredTests[i].Name < filteredTests[j].Name
		})
	}
	var pkgList []*Package
	for _, k := range pkgOrder {
		pkgList = append(pkgList, packages[k])
	}
	hasNonNoTest := false
	for _, p := range pkgList {
		if !p.IsNoTest {
			hasNonNoTest = true
			break
		}
	}
	var finalPkgList []*Package
	for _, p := range pkgList {
		if p.IsNoTest {
			if flagNoTests || !hasNonNoTest {
				finalPkgList = append(finalPkgList, p)
			}
		} else {
			// For package-level skip without IsNoTest and with empty name, original still shows? In our earlier, "only pkg skip" case finalPkgList includes it even though Name empty. So include.
			finalPkgList = append(finalPkgList, p)
		}
	}
	switch flagSort {
	case "name":
		sort.Slice(finalPkgList, func(i, j int) bool { return finalPkgList[i].Name < finalPkgList[j].Name })
	case "elapsed":
		sort.Slice(finalPkgList, func(i, j int) bool {
			if finalPkgList[i].Elapsed != finalPkgList[j].Elapsed {
				return finalPkgList[i].Elapsed > finalPkgList[j].Elapsed
			}
			return finalPkgList[i].Name < finalPkgList[j].Name
		})
	case "cover":
		sort.Slice(finalPkgList, func(i, j int) bool {
			if finalPkgList[i].CoverPct != finalPkgList[j].CoverPct {
				return finalPkgList[i].CoverPct > finalPkgList[j].CoverPct
			}
			return finalPkgList[i].Name < finalPkgList[j].Name
		})
	}
	exitCode := 0
	for _, p := range finalPkgList {
		if p.Status == "FAIL" || p.Status == "PANIC" {
			exitCode = 1
			break
		}
	}
	switch flagFormat {
	case "basic":
		renderBasic(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	case "plain":
		renderPlain(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	case "markdown":
		renderMarkdown(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	}
	os.Exit(exitCode)
}

// helpers
func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
func padCenter(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}
func padCenterVisible(s string, width int) string {
	vis := stripANSI(s)
	l := utf8.RuneCountInString(vis)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}
func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return " " + s + strings.Repeat(" ", width-1-l)
}
func stripANSI(s string) string {
	re := regexp.MustCompile("\x1b\\[[0-9;]*m")
	return re.ReplaceAllString(s, "")
}
func colorStatus(s string) string {
	switch s {
	case "PASS":
		return "\x1b[92m" + s + "\x1b[0m"
	case "FAIL":
		return "\x1b[91m" + s + "\x1b[0m"
	case "SKIP":
		return "\x1b[93m" + s + "\x1b[0m"
	case "NOTEST":
		return "\x1b[93m" + s + "\x1b[0m"
	case "PANIC":
		return "\x1b[91m" + s + "\x1b[0m"
	default:
		return s
	}
}
func splitTestNameSmallscreen(name string) []string {
	if utf8.RuneCountInString(name) <= 32 || !strings.Contains(name, "/") {
		return []string{name}
	}
	parts := strings.Split(name, "/")
	var lines []string
	for i, part := range parts {
		if i == 0 {
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, ch+" …")
						} else {
							lines = append(lines, ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "   "+ch+" …")
						} else {
							lines = append(lines, "   "+ch)
						}
					}
				}
			}
		} else {
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, "  /"+part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, "  /"+ch+" …")
						} else {
							lines = append(lines, "  /"+ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "   "+ch+" …")
						} else {
							lines = append(lines, "   "+ch)
						}
					}
				}
			}
		}
	}
	return lines
}
func chunkString(s string, size int) []string {
	var chunks []string
	runes := []rune(s)
	for len(runes) > 0 {
		if len(runes) <= size {
			chunks = append(chunks, string(runes))
			break
		}
		chunks = append(chunks, string(runes[:size]))
		runes = runes[size:]
	}
	return chunks
}
func renderBasic(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
