cat <<'GO' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

type Event struct {
	Time    string  `json:"Time"`
	Action  string  `json:"Action"`
	Package string  `json:"Package"`
	Test    string  `json:"Test"`
	Output  string  `json:"Output"`
	Elapsed float64 `json:"Elapsed"`
}

type Test struct {
	Name        string
	Package     string
	OrigPackage string
	Elapsed     float64
	Status      string
	Output      []string
	IsPanic     bool
	SortCover   float64
	Index       int
}

type Package struct {
	OrigName         string
	TrimmedName      string
	Name             string
	Elapsed          float64
	ElapsedStr       string
	ElapsedIsCached  bool
	Cover            string
	CoverPct         float64
	Status           string
	PassCount        int
	FailCount        int
	SkipCount        int
	Tests            map[string]*Test
	Outputs          []string
	FailedTests      []*Test
	IsNoTest         bool
	NoTestMessage    string
	HasPanic         bool
	PanicTest        *Test
	PkgSkipCount     int
}

func formatElapsedPackage(f float64, isCached bool) string {
	if isCached {
		return "(cached)"
	}
	return fmt.Sprintf("%.2fs", f)
}
func formatElapsedTest(f float64) string {
	return fmt.Sprintf("%.2f", f)
}
func formatTimestamp(tStr string) string {
	for _, l := range []string{time.RFC3339Nano, time.RFC3339} {
		if tm, err := time.Parse(l, tStr); err == nil {
			return tm.UTC().Format("2006-01-02T15:04:05Z")
		}
	}
	if idx := strings.Index(tStr, "."); idx != -1 {
		return tStr[:idx] + "Z"
	}
	return tStr
}

func main() {
	var (
		showHelp         bool
		showVersion      bool
		flagAll          bool
		flagPass         bool
		flagSkip         bool
		flagNoTests      bool
		flagSmallScreen  bool
		flagSlow         int
		flagSort         string
		flagNoColor      bool
		flagFormat       string
		flagFile         string
		flagFollow       bool
		flagFollowOutput string
		flagIncludeTS    bool
		flagProgress     bool
		flagCompare      string
		flagTrimPath     string
	)
	flag.BoolVar(&showHelp, "h", false, "")
	flag.BoolVar(&showVersion, "v", false, "")
	flag.BoolVar(&flagAll, "all", false, "")
	flag.BoolVar(&flagPass, "pass", false, "")
	flag.BoolVar(&flagSkip, "skip", false, "")
	flag.BoolVar(&flagNoTests, "notests", false, "")
	flag.BoolVar(&flagSmallScreen, "smallscreen", false, "")
	flag.IntVar(&flagSlow, "slow", 0, "")
	flag.StringVar(&flagSort, "sort", "name", "")
	flag.BoolVar(&flagNoColor, "nocolor", false, "")
	flag.StringVar(&flagFormat, "format", "basic", "")
	flag.StringVar(&flagFile, "file", "", "")
	flag.BoolVar(&flagFollow, "follow", false, "")
	flag.StringVar(&flagFollowOutput, "follow-output", "", "")
	flag.BoolVar(&flagIncludeTS, "include-timestamp", false, "")
	flag.BoolVar(&flagProgress, "progress", false, "")
	flag.StringVar(&flagCompare, "compare", "", "")
	flag.StringVar(&flagTrimPath, "trimpath", "", "")
	flag.Usage = func() {
		fmt.Fprint(os.Stdout, "Usage:\n    go test ./... -json | tparse [options...]\n    go test [packages...] -json | tparse [options...]\n    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out\n\nOptions:\n    -h                 Show help.\n    -v                 Show version.\n    -all               Display table event for pass and skip. (Failed items always displayed)\n    -pass              Display table for passed tests.\n    -skip              Display table for skipped tests.\n    -notests           Display packages containing no test files or empty test files.\n    -smallscreen       Split subtest names vertically to fit on smaller screens.\n    -slow              Number of slowest tests to display. Default is 0, display all.\n    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.\n    -nocolor           Disable all colors. (NO_COLOR also supported)\n    -format            The output format for tables [basic, plain, markdown]. Default is basic.\n    -file              Read test output from a file.\n    -follow            Follow raw output from go test to stdout.\n    -follow-output     Write raw output from go test to a file (takes precedence over -follow).\n    -include-timestamp Include timestamps in follow output. \n    -progress          Print a single summary line for each package. Useful for long running test suites.\n    -compare           Compare against a previous test output file. (experimental)\n    -trimpath          Remove path prefix from package names in output, simplifying their display.\n")
	}
	flag.Parse()
	if showHelp {
		flag.Usage()
		return
	}
	if showVersion {
		fmt.Fprintln(os.Stdout, "tparse version: (devel)")
		return
	}
	if flagSort != "name" && flagSort != "elapsed" && flagSort != "cover" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -sort flag must be one of: name, elapsed or cover\n", flagSort)
		return
	}
	if flagFormat != "basic" && flagFormat != "plain" && flagFormat != "markdown" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -format flag must be one of: basic, plain or markdown\n", flagFormat)
		return
	}
	colorEnabled := true
	if flagNoColor {
		colorEnabled = false
	}
	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		colorEnabled = false
	}
	var reader io.Reader
	if flagFile != "" {
		f, err := os.Open(flagFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "open %s: %s\n", flagFile, err.Error())
			os.Exit(1)
		}
		defer f.Close()
		reader = f
	} else {
		fi, err := os.Stdin.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		reader = os.Stdin
	}
	var followFile *os.File
	if flagFollowOutput != "" {
		f, err := os.Create(flagFollowOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to create follow output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		followFile = f
	}
	if flagCompare != "" {
		if _, err := os.Open(flagCompare); err != nil {
			fmt.Fprintf(os.Stderr, "open %s: %s\n", flagCompare, err.Error())
			os.Exit(1)
		}
	}
	coverPctRe := regexp.MustCompile(`coverage:\s*([0-9.]+)%`)
	noTestFilesStr := "[no test files]"
	filterRunRe := regexp.MustCompile(`^\s*=== RUN`)
	filterPauseRe := regexp.MustCompile(`^\s*=== PAUSE`)
	filterContRe := regexp.MustCompile(`^\s*=== CONT`)
	filterPassRe := regexp.MustCompile(`^\s*--- PASS:`)
	filterSkipRe := regexp.MustCompile(`^\s*--- SKIP:`)

	type Completion struct {
		Package         string
		Status          string
		Elapsed         float64
		ElapsedStr      string
		ElapsedIsCached bool
		IsNoTest        bool
	}
	packages := make(map[string]*Package)
	pkgOrder := []string{}
	completionOrder := []Completion{}
	hasParsable := false
	scanner := bufio.NewScanner(reader)
	buf := make([]byte, 0, 1024*1024)
	scanner.Buffer(buf, 10*1024*1024)
	testIndex := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var ev Event
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			continue
		}
		hasParsable = true
		trimmedPkg := ev.Package
		if flagTrimPath != "" && strings.HasPrefix(ev.Package, flagTrimPath) {
			trimmedPkg = strings.TrimPrefix(ev.Package, flagTrimPath)
		}
		displayPkg := trimmedPkg
		if flagSmallScreen && displayPkg != "" {
			parts := strings.Split(displayPkg, "/")
			last := ""
			for i := len(parts) - 1; i >= 0; i-- {
				if parts[i] != "" {
					last = parts[i]
					break
				}
			}
			if last != "" {
				displayPkg = last
			}
		}
		origKey := ev.Package
		if origKey == "" {
			if displayPkg != "" {
				origKey = displayPkg
			} else {
				origKey = "__empty__"
			}
		}
		pkg, ok := packages[origKey]
		if !ok {
			pkg = &Package{
				OrigName:    ev.Package,
				TrimmedName: trimmedPkg,
				Name:        displayPkg,
				Tests:       make(map[string]*Test),
				Cover:       "--",
			}
			packages[origKey] = pkg
			pkgOrder = append(pkgOrder, origKey)
		}
		if ev.Action == "output" {
			if strings.Contains(ev.Output, "coverage:") {
				m := coverPctRe.FindStringSubmatch(ev.Output)
				if len(m) >= 2 {
					pkg.Cover = m[1] + "%"
					if f, err := strconv.ParseFloat(m[1], 64); err == nil {
						pkg.CoverPct = f
					}
				}
			}
			if strings.Contains(ev.Output, noTestFilesStr) {
				pkg.IsNoTest = true
				pkg.NoTestMessage = noTestFilesStr
				pkg.Status = "NOTEST"
			}
			if strings.Contains(ev.Output, "(cached)") {
				pkg.ElapsedIsCached = true
				pkg.ElapsedStr = "(cached)"
			}
			shouldFilter := false
			if filterRunRe.MatchString(ev.Output) || filterPauseRe.MatchString(ev.Output) || filterContRe.MatchString(ev.Output) || filterPassRe.MatchString(ev.Output) || filterSkipRe.MatchString(ev.Output) {
				shouldFilter = true
			}
			if !shouldFilter {
				followStr := ev.Output
				if flagIncludeTS {
					followStr = formatTimestamp(ev.Time) + " " + followStr
				}
				if followFile != nil {
					_, _ = followFile.WriteString(followStr)
				} else if flagFollow {
					fmt.Fprint(os.Stdout, followStr)
				}
			}
			if ev.Test != "" {
				t, exists := pkg.Tests[ev.Test]
				if !exists {
					t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
					testIndex++
					pkg.Tests[ev.Test] = t
				}
				t.Output = append(t.Output, ev.Output)
				if strings.Contains(ev.Output, "panic:") {
					t.IsPanic = true
					pkg.HasPanic = true
					if pkg.PanicTest == nil {
						pkg.PanicTest = t
					}
				}
			} else {
				pkg.Outputs = append(pkg.Outputs, ev.Output)
				if strings.Contains(ev.Output, "panic:") {
					pkg.HasPanic = true
				}
			}
			continue
		}
		switch ev.Action {
		case "run":
			t, exists := pkg.Tests[ev.Test]
			if !exists {
				t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
				testIndex++
				pkg.Tests[ev.Test] = t
			}
			t.Package = displayPkg
		case "pass", "fail", "skip":
			if ev.Test != "" {
				t, exists := pkg.Tests[ev.Test]
				if !exists {
					t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
					testIndex++
					pkg.Tests[ev.Test] = t
				}
				t.Status = strings.ToUpper(ev.Action)
				t.Elapsed = ev.Elapsed
				t.Package = displayPkg
			} else {
				pkg.Elapsed = ev.Elapsed
				if !pkg.ElapsedIsCached {
					if pkg.IsNoTest {
						pkg.Status = "NOTEST"
					} else {
						switch ev.Action {
						case "pass":
							pkg.Status = "PASS"
						case "fail":
							pkg.Status = "FAIL"
						case "skip":
							if pkg.IsNoTest {
								pkg.Status = "NOTEST"
							} else {
								pkg.Status = ""
								pkg.PkgSkipCount++
							}
						}
					}
				} else {
					if pkg.Status == "" || pkg.Status == "PASS" {
						pkg.Status = "PASS"
					}
				}
				if pkg.HasPanic {
					pkg.Status = "PANIC"
				}
				comp := Completion{Package: ev.Package, Status: pkg.Status, Elapsed: pkg.Elapsed, ElapsedStr: pkg.ElapsedStr, ElapsedIsCached: pkg.ElapsedIsCached, IsNoTest: pkg.IsNoTest}
				if comp.ElapsedStr == "" {
					if comp.ElapsedIsCached {
						comp.ElapsedStr = "(cached)"
					} else {
						comp.ElapsedStr = formatElapsedPackage(comp.Elapsed, false)
					}
				}
				if comp.Status == "" {
					comp.Status = strings.ToUpper(ev.Action)
				}
				completionOrder = append(completionOrder, comp)
			}
		}
	}
	if !hasParsable {
		fmt.Fprintln(os.Stderr, "no parsable events: Make sure to run go test with -json flag")
		os.Exit(1)
	}
	for _, key := range pkgOrder {
		pkg := packages[key]
		pass, fail, skip := 0, 0, 0
		for _, t := range pkg.Tests {
			switch t.Status {
			case "PASS":
				pass++
			case "FAIL":
				fail++
			case "SKIP":
				skip++
			}
		}
		pkg.PassCount = pass
		pkg.FailCount = fail
		pkg.SkipCount = skip + pkg.PkgSkipCount
		if pkg.ElapsedStr == "" {
			if pkg.ElapsedIsCached {
				pkg.ElapsedStr = "(cached)"
			} else {
				pkg.ElapsedStr = formatElapsedPackage(pkg.Elapsed, false)
			}
		}
		trimmed := pkg.OrigName
		if flagTrimPath != "" && strings.HasPrefix(pkg.OrigName, flagTrimPath) {
			trimmed = strings.TrimPrefix(pkg.OrigName, flagTrimPath)
		}
		pkg.TrimmedName = trimmed
		display := trimmed
		if flagSmallScreen && display != "" {
			parts := strings.Split(display, "/")
			last := ""
			for i := len(parts) - 1; i >= 0; i-- {
				if parts[i] != "" {
					last = parts[i]
					break
				}
			}
			if last != "" {
				display = last
			}
		}
		pkg.Name = display
		for _, t := range pkg.Tests {
			t.Package = pkg.Name
			t.SortCover = pkg.CoverPct
		}
		var failed []*Test
		for _, t := range pkg.Tests {
			if t.Status == "FAIL" || t.IsPanic {
				failed = append(failed, t)
			}
		}
		sort.Slice(failed, func(i, j int) bool { return failed[i].Name < failed[j].Name })
		pkg.FailedTests = failed
	}
	if flagProgress {
		for _, comp := range completionOrder {
			status := comp.Status
			if status == "" {
				status = "SKIP"
			}
			elapsedStr := comp.ElapsedStr
			if elapsedStr == "" {
				if comp.ElapsedIsCached {
					elapsedStr = "(cached)"
				} else {
					elapsedStr = formatElapsedPackage(comp.Elapsed, false)
				}
			}
			fmt.Fprintf(os.Stdout, "[%s]\t%10s\t%s\n", status, elapsedStr, comp.Package)
		}
	}
	showTestTable := flagAll || flagPass || flagSkip
	var allTests []*Test
	for _, key := range pkgOrder {
		for _, t := range packages[key].Tests {
			allTests = append(allTests, t)
		}
	}
	var filteredTests []*Test
	for _, t := range allTests {
		if !showTestTable {
			continue
		}
		include := false
		if flagAll {
			include = true
		} else {
			if t.Status == "FAIL" {
				include = true
			} else if t.Status == "PASS" && flagPass {
				include = true
			} else if t.Status == "SKIP" && flagSkip {
				include = true
			} else if t.Status == "" && (flagSkip || flagAll) {
				include = true
			}
		}
		if include {
			filteredTests = append(filteredTests, t)
		}
	}
	if flagSlow > 0 {
		var passes []*Test
		var others []*Test
		for _, t := range filteredTests {
			if t.Status == "PASS" {
				passes = append(passes, t)
			} else {
				others = append(others, t)
			}
		}
		sort.Slice(passes, func(i, j int) bool { return passes[i].Elapsed > passes[j].Elapsed })
		if len(passes) > flagSlow {
			passes = passes[:flagSlow]
		}
		filteredTests = append(passes, others...)
	}
	switch flagSort {
	case "name":
		sort.Slice(filteredTests, func(i, j int) bool {
			if filteredTests[i].Name != filteredTests[j].Name {
				return filteredTests[i].Name < filteredTests[j].Name
			}
			return filteredTests[i].Package < filteredTests[j].Package
		})
	case "elapsed":
		sort.Slice(filteredTests, func(i, j int) bool {
			if filteredTests[i].Elapsed != filteredTests[j].Elapsed {
				return filteredTests[i].Elapsed > filteredTests[j].Elapsed
			}
			return filteredTests[i].Name < filteredTests[j].Name
		})
	case "cover":
		sort.Slice(filteredTests, func(i, j int) bool {
			if filteredTests[i].SortCover != filteredTests[j].SortCover {
				return filteredTests[i].SortCover > filteredTests[j].SortCover
			}
			if filteredTests[i].Elapsed != filteredTests[j].Elapsed {
				return filteredTests[i].Elapsed > filteredTests[j].Elapsed
			}
			return filteredTests[i].Name < filteredTests[j].Name
		})
	}
	var pkgList []*Package
	for _, k := range pkgOrder {
		pkgList = append(pkgList, packages[k])
	}
	hasNonNoTest := false
	for _, p := range pkgList {
		if !p.IsNoTest {
			hasNonNoTest = true
			break
		}
	}
	var finalPkgList []*Package
	for _, p := range pkgList {
		if p.IsNoTest {
			if flagNoTests || !hasNonNoTest {
				finalPkgList = append(finalPkgList, p)
			}
		} else {
			finalPkgList = append(finalPkgList, p)
		}
	}
	switch flagSort {
	case "name":
		sort.Slice(finalPkgList, func(i, j int) bool { return finalPkgList[i].Name < finalPkgList[j].Name })
	case "elapsed":
		sort.Slice(finalPkgList, func(i, j int) bool {
			if finalPkgList[i].Elapsed != finalPkgList[j].Elapsed {
				return finalPkgList[i].Elapsed > finalPkgList[j].Elapsed
			}
			return finalPkgList[i].Name < finalPkgList[j].Name
		})
	case "cover":
		sort.Slice(finalPkgList, func(i, j int) bool {
			if finalPkgList[i].CoverPct != finalPkgList[j].CoverPct {
				return finalPkgList[i].CoverPct > finalPkgList[j].CoverPct
			}
			return finalPkgList[i].Name < finalPkgList[j].Name
		})
	}
	exitCode := 0
	for _, p := range finalPkgList {
		if p.Status == "FAIL" || p.Status == "PANIC" {
			exitCode = 1
			break
		}
	}
	switch flagFormat {
	case "basic":
		renderBasic(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	case "plain":
		renderPlain(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	case "markdown":
		renderMarkdown(os.Stdout, filteredTests, finalPkgList, colorEnabled, flagSmallScreen, showTestTable)
	}
	os.Exit(exitCode)
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
func padCenter(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}
func padCenterVisible(s string, width int) string {
	vis := stripANSI(s)
	l := utf8.RuneCountInString(vis)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}
func padLeft(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return " " + s + strings.Repeat(" ", width-1-l)
}
func stripANSI(s string) string {
	re := regexp.MustCompile("\x1b\\[[0-9;]*m")
	return re.ReplaceAllString(s, "")
}
func colorStatus(s string) string {
	switch s {
	case "PASS":
		return "\x1b[92m" + s + "\x1b[0m"
	case "FAIL":
		return "\x1b[91m" + s + "\x1b[0m"
	case "SKIP":
		return "\x1b[93m" + s + "\x1b[0m"
	case "NOTEST":
		return "\x1b[93m" + s + "\x1b[0m"
	case "PANIC":
		return "\x1b[91m" + s + "\x1b[0m"
	default:
		return s
	}
}
func splitTestNameSmallscreen(name string) []string {
	if utf8.RuneCountInString(name) <= 32 || !strings.Contains(name, "/") {
		return []string{name}
	}
	parts := strings.Split(name, "/")
	var lines []string
	for i, part := range parts {
		if i == 0 {
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, ch+" …")
						} else {
							lines = append(lines, ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "  "+ch+" …")
						} else {
							lines = append(lines, "  "+ch)
						}
					}
				}
			}
		} else {
			if utf8.RuneCountInString(part) <= 30 {
				lines = append(lines, " /"+part)
			} else {
				chunks := chunkString(part, 30)
				for j, ch := range chunks {
					if j == 0 {
						if len(chunks) > 1 {
							lines = append(lines, " /"+ch+" …")
						} else {
							lines = append(lines, " /"+ch)
						}
					} else {
						if j < len(chunks)-1 {
							lines = append(lines, "  "+ch+" …")
						} else {
							lines = append(lines, "  "+ch)
						}
					}
				}
			}
		}
	}
	return lines
}
func chunkString(s string, size int) []string {
	var chunks []string
	runes := []rune(s)
	for len(runes) > 0 {
		if len(runes) <= size {
			chunks = append(chunks, string(runes))
			break
		}
		chunks = append(chunks, string(runes[:size]))
		runes = runes[size:]
	}
	return chunks
}
func renderBasic(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
	if showTest && len(tests) > 0 {
		renderTestTableBasic(w, tests, color, smallscreen)
	}
	for _, pkg := range pkgs {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			renderFailureGrouping(w, pkg, color)
		}
	}
	if len(pkgs) > 0 {
		renderPackageTableBasic(w, pkgs, color)
	}
}
func renderPlain(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
	if showTest && len(tests) > 0 {
		renderTestTableBasic(w, tests, color, smallscreen)
	}
	for _, pkg := range pkgs {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			renderFailureGrouping(w, pkg, color)
		}
	}
	if len(pkgs) > 0 {
		renderPackageTableBasic(w, pkgs, color)
	}
}
func renderMarkdown(w io.Writer, tests []*Test, pkgs []*Package, color bool, smallscreen bool, showTest bool) {
	grouped := make(map[string][]*Test)
	for _, t := range tests {
		grouped[t.Package] = append(grouped[t.Package], t)
	}
	if showTest {
		for _, pkg := range pkgs {
			ts, ok := grouped[pkg.Name]
			if !ok || len(ts) == 0 {
				continue
			}
			sort.Slice(ts, func(i, j int) bool { return ts[i].Name < ts[j].Name })
			orig := pkg.OrigName
			if orig == "" {
				orig = pkg.Name
			}
			if orig == "__empty__" {
				orig = ""
			}
			fmt.Fprintf(w, "## 📦 Package `%s`\n\n", orig)
			fmt.Fprintf(w, "Tests: ✓ %d passed | %d skipped | %d failed\n\n", pkg.PassCount, pkg.SkipCount, pkg.FailCount)
			fmt.Fprintln(w, "<details>")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "<summary>Click for test summary</summary>")
			fmt.Fprintln(w, "")
			renderTestTableMarkdownInner(w, ts, color, smallscreen)
			fmt.Fprintln(w, "</details>")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "")
		}
	}
	for _, pkg := range pkgs {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" {
			if pkg.HasPanic && pkg.PanicTest != nil {
				if color {
					fmt.Fprintf(w, "## 🔴 PANIC • %s • %s\n\n", pkg.OrigName, pkg.PanicTest.Name)
				} else {
					fmt.Fprintf(w, "## PANIC • %s • %s\n\n", pkg.OrigName, pkg.PanicTest.Name)
				}
			} else {
				if color {
					fmt.Fprintf(w, "## 🔴 FAIL • %s\n\n", pkg.OrigName)
				} else {
					fmt.Fprintf(w, "## FAIL • %s\n\n", pkg.OrigName)
				}
			}
			fmt.Fprintln(w, "```")
			fmt.Fprintln(w, "")
			var failOutputs []string
			for _, t := range pkg.FailedTests {
				for _, out := range t.Output {
					if isFilteredForFailure(out) {
						continue
					}
					failOutputs = append(failOutputs, out)
				}
			}
			if len(failOutputs) > 0 {
				for _, o := range failOutputs {
					fmt.Fprint(w, o)
					if !strings.HasSuffix(o, "\n") {
						fmt.Fprintln(w)
					}
				}
			}
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "```")
			fmt.Fprintln(w, "")
		}
	}
	if len(pkgs) > 0 {
		renderPackageTableMarkdown(w, pkgs, color)
	}
}
func isFilteredForFailure(out string) bool {
	trim := strings.TrimLeft(out, " \t")
	if strings.HasPrefix(trim, "=== RUN") || strings.HasPrefix(trim, "=== PAUSE") || strings.HasPrefix(trim, "=== CONT") || strings.HasPrefix(trim, "--- PASS:") || strings.HasPrefix(trim, "--- SKIP:") {
		return true
	}
	return false
}
func renderFailureGrouping(w io.Writer, pkg *Package, color bool) {
	if pkg.Status == "PANIC" {
		var headerText string
		if pkg.PanicTest != nil {
			headerText = fmt.Sprintf("   PANIC  package: %s • %s   ", pkg.OrigName, pkg.PanicTest.Name)
		} else {
			headerText = fmt.Sprintf("   PANIC  package: %s   ", pkg.OrigName)
		}
		width := utf8.RuneCountInString(headerText)
		top := "┏" + strings.Repeat("━", width) + "┓"
		mid := "┃" + headerText + "┃"
		bottom := "┗" + strings.Repeat("━", width) + "┛"
		if color {
			top = "\x1b[38;5;103m" + top + "\x1b[0m"
			mid = "\x1b[38;5;103m┃\x1b[0m" + headerText + "\x1b[38;5;103m┃\x1b[0m"
			bottom = "\x1b[38;5;103m" + bottom + "\x1b[0m"
		}
		fmt.Fprintln(w, top)
		fmt.Fprintln(w, mid)
		fmt.Fprintln(w, bottom)
		fmt.Fprintln(w, "")
		if pkg.PanicTest != nil {
			for _, out := range pkg.PanicTest.Output {
				fmt.Fprint(w, out)
			}
		} else {
			for _, out := range pkg.Outputs {
				fmt.Fprint(w, out)
			}
		}
		fmt.Fprintln(w, "")
		return
	}
	if len(pkg.FailedTests) == 0 {
		return
	}
	headerText := fmt.Sprintf("   FAIL  package: %s   ", pkg.OrigName)
	width := utf8.RuneCountInString(headerText)
	top := "┏" + strings.Repeat("━", width) + "┓"
	mid := "┃" + headerText + "┃"
	bottom := "┗" + strings.Repeat("━", width) + "┛"
	if color {
		top = "\x1b[38;5;103m" + top + "\x1b[0m"
		mid = "\x1b[38;5;103m┃\x1b[0m   \x1b[91m\x1b[91mFAIL\x1b[0m\x1b[0m  package: " + pkg.OrigName + "   \x1b[38;5;103m┃\x1b[0m"
		bottom = "\x1b[38;5;103m" + bottom + "\x1b[0m"
	}
	fmt.Fprintln(w, top)
	fmt.Fprintln(w, mid)
	fmt.Fprintln(w, bottom)
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "")
	for idx, t := range pkg.FailedTests {
		if idx > 0 {
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, strings.Repeat("─", 96))
			fmt.Fprintln(w, strings.Repeat(" ", 96))
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "")
		}
		for _, out := range t.Output {
			if isFilteredForFailure(out) {
				continue
			}
			fmt.Fprint(w, out)
			if !strings.HasSuffix(out, "\n") {
				fmt.Fprintln(w)
			}
		}
	}
	fmt.Fprintln(w, "")
}
func renderTestTableBasic(w io.Writer, tests []*Test, color bool, smallscreen bool) {
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	type Row struct {
		Status    string
		Elapsed   string
		TestLines []string
		Package   string
	}
	var rows []Row
	for _, t := range tests {
		rows = append(rows, Row{
			Status:    t.Status,
			Elapsed:   formatElapsedTest(t.Elapsed),
			TestLines: splitTestNameSmallscreen(t.Name),
			Package:   t.Package,
		})
	}
	maxVals := []int{len(headers[0]), len(headers[1]), len(headers[2]), len(headers[3])}
	for _, r := range rows {
		if len(r.Status) > maxVals[0] {
			maxVals[0] = len(r.Status)
		}
		if len(r.Elapsed) > maxVals[1] {
			maxVals[1] = len(r.Elapsed)
		}
		for _, tl := range r.TestLines {
			if utf8.RuneCountInString(tl) > maxVals[2] {
				maxVals[2] = utf8.RuneCountInString(tl)
			}
		}
		if utf8.RuneCountInString(r.Package) > maxVals[3] {
			maxVals[3] = utf8.RuneCountInString(r.Package)
		}
	}
	widths := make([]int, 4)
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")
	fmt.Fprint(w, "│")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "│")
	}
	fmt.Fprintln(w, "")
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")
	for _, r := range rows {
		for lineIdx, tLine := range r.TestLines {
			fmt.Fprint(w, "│")
			var statusCell string
			if lineIdx == 0 {
				statusCell = r.Status
			}
			if color && statusCell != "" {
				statusCell = colorStatus(statusCell)
			}
			fmt.Fprint(w, padCenterVisible(statusCell, widths[0]))
			fmt.Fprint(w, "│")
			var elapsedCell string
			if lineIdx == 0 {
				elapsedCell = r.Elapsed
			}
			fmt.Fprint(w, padCenter(elapsedCell, widths[1]))
			fmt.Fprint(w, "│")
			fmt.Fprint(w, padLeft(tLine, widths[2]))
			fmt.Fprint(w, "│")
			var pkgCell string
			if lineIdx == 0 {
				pkgCell = r.Package
			}
			fmt.Fprint(w, padLeft(pkgCell, widths[3]))
			fmt.Fprint(w, "│")
			fmt.Fprintln(w, "")
		}
	}
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}
func renderPackageTableBasic(w io.Writer, pkgs []*Package, color bool) {
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	maxVals := make([]int, len(headers))
	for i, h := range headers {
		maxVals[i] = len(h)
	}
	type RowLines struct{ Lines [][]string }
	var allRows []RowLines
	for _, pkg := range pkgs {
		status := pkg.Status
		elapsed := pkg.ElapsedStr
		pkgName := pkg.Name
		cover := pkg.Cover
		var passStr, failStr, skipStr string
		if pkg.IsNoTest {
			passStr = "--"
			failStr = "--"
			skipStr = "--"
		} else {
			passStr = strconv.Itoa(pkg.PassCount)
			failStr = strconv.Itoa(pkg.FailCount)
			skipStr = strconv.Itoa(pkg.SkipCount)
		}
		if pkg.IsNoTest {
			line1 := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			line2 := []string{"", "", pkg.NoTestMessage, "", "", "", ""}
			allRows = append(allRows, RowLines{Lines: [][]string{line1, line2}})
			for i, cell := range line1 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
			for i, cell := range line2 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		} else {
			line := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			allRows = append(allRows, RowLines{Lines: [][]string{line}})
			for i, cell := range line {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
		}
	}
	widths := make([]int, len(headers))
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	fmt.Fprint(w, "╭")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┬")
		}
	}
	fmt.Fprintln(w, "╮")
	fmt.Fprint(w, "│")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		fmt.Fprint(w, "│")
	}
	fmt.Fprintln(w, "")
	fmt.Fprint(w, "├")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┼")
		}
	}
	fmt.Fprintln(w, "┤")
	for _, rl := range allRows {
		for _, line := range rl.Lines {
			fmt.Fprint(w, "│")
			for i, cell := range line {
				var padded string
				if i == 2 {
					padded = padLeft(cell, widths[i])
				} else {
					if i == 0 && color && cell != "" {
						padded = padCenterVisible(colorStatus(cell), widths[i])
					} else {
						padded = padCenter(cell, widths[i])
					}
				}
				fmt.Fprint(w, padded)
				fmt.Fprint(w, "│")
			}
			fmt.Fprintln(w, "")
		}
	}
	fmt.Fprint(w, "╰")
	for i, wd := range widths {
		fmt.Fprint(w, strings.Repeat("─", wd))
		if i < len(widths)-1 {
			fmt.Fprint(w, "┴")
		}
	}
	fmt.Fprintln(w, "╯")
}
func renderTestTableMarkdownInner(w io.Writer, tests []*Test, color bool, smallscreen bool) {
	headers := []string{"Status", "Elapsed", "Test"}
	type Row struct {
		Status    string
		Elapsed   string
		TestLines []string
	}
	var rows []Row
	maxVals := []int{len(headers[0]), len(headers[1]), len(headers[2])}
