}

type Test struct {
	Name        string
	Package     string
	OrigPackage string
	Elapsed     float64
	Status      string
	Output      []string
	IsPanic     bool
	SortCover   float64
	Index       int
}

type Package struct {
	OrigName         string
	TrimmedName      string
	Name             string
	Elapsed          float64
	ElapsedStr       string
	ElapsedIsCached  bool
	Cover            string
	CoverPct         float64
	Status           string
	PassCount        int
	FailCount        int
	SkipCount        int
	Tests            map[string]*Test
	Outputs          []string
	FailedTests      []*Test
	IsNoTest         bool
	NoTestMessage    string
	HasPanic         bool
	PanicTest        *Test
	PkgSkipCount     int
}

func formatElapsedPackage(f float64, isCached bool) string {
	if isCached {
		return "(cached)"
	}
	return fmt.Sprintf("%.2fs", f)
}
func formatElapsedTest(f float64) string {
	return fmt.Sprintf("%.2f", f)
}
func formatTimestamp(tStr string) string {
	for _, l := range []string{time.RFC3339Nano, time.RFC3339} {
		if tm, err := time.Parse(l, tStr); err == nil {
			return tm.UTC().Format("2006-01-02T15:04:05Z")
		}
	}
	if idx := strings.Index(tStr, "."); idx != -1 {
		return tStr[:idx] + "Z"
	}
	return tStr
}

func main() {
