				}
			}
			if ev.Test != "" {
				t, exists := pkg.Tests[ev.Test]
				if !exists {
					t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
					testIndex++
					pkg.Tests[ev.Test] = t
				}
				t.Output = append(t.Output, ev.Output)
				if strings.Contains(ev.Output, "panic:") {
					t.IsPanic = true
					pkg.HasPanic = true
					if pkg.PanicTest == nil {
						pkg.PanicTest = t
					}
				}
			} else {
				pkg.Outputs = append(pkg.Outputs, ev.Output)
				if strings.Contains(ev.Output, "panic:") {
					pkg.HasPanic = true
				}
			}
			continue
		}
		switch ev.Action {
		case "run":
			t, exists := pkg.Tests[ev.Test]
			if !exists {
				t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
				testIndex++
				pkg.Tests[ev.Test] = t
			}
			t.Package = displayPkg
		case "pass", "fail", "skip":
			if ev.Test != "" {
				t, exists := pkg.Tests[ev.Test]
				if !exists {
					t = &Test{Name: ev.Test, Package: displayPkg, OrigPackage: ev.Package, Index: testIndex}
					testIndex++
					pkg.Tests[ev.Test] = t
				}
				t.Status = strings.ToUpper(ev.Action)
				t.Elapsed = ev.Elapsed
				t.Package = displayPkg
			} else {
				pkg.Elapsed = ev.Elapsed
				if !pkg.ElapsedIsCached {
					if pkg.IsNoTest {
						pkg.Status = "NOTEST"
					} else {
						switch ev.Action {
						case "pass":
							pkg.Status = "PASS"
						case "fail":
							pkg.Status = "FAIL"
						case "skip":
							if pkg.IsNoTest {
								pkg.Status = "NOTEST"
							} else {
								pkg.Status = ""
								pkg.PkgSkipCount++
							}
						}
					}
				} else {
					if pkg.Status == "" || pkg.Status == "PASS" {
						pkg.Status = "PASS"
					}
				}
				if pkg.HasPanic {
					pkg.Status = "PANIC"
				}
