func renderPackageTableMarkdown(w io.Writer, pkgs []*Package, color bool) {
	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	maxVals := make([]int, len(headers))
	for i, h := range headers {
		maxVals[i] = len(h)
	}
	type RowLines struct{ Lines [][]string }
	var allRows []RowLines
	for _, pkg := range pkgs {
		status := pkg.Status
		if color {
			switch status {
			case "PASS":
				status = "🟢 PASS"
			case "FAIL":
				status = "🔴 FAIL"
			case "SKIP":
				status = "🟡 SKIP"
			case "NOTEST":
				status = "🟡 NOTEST"
			case "PANIC":
				status = "🔴 PANIC"
			}
		}
		elapsed := pkg.ElapsedStr
		pkgName := pkg.OrigName
		if pkgName == "__empty__" {
			pkgName = ""
		}
		cover := pkg.Cover
		var passStr, failStr, skipStr string
		if pkg.IsNoTest {
			passStr = "--"
			failStr = "--"
			skipStr = "--"
		} else {
			passStr = strconv.Itoa(pkg.PassCount)
			failStr = strconv.Itoa(pkg.FailCount)
			skipStr = strconv.Itoa(pkg.SkipCount)
		}
		if pkg.IsNoTest {
			line1 := []string{status, elapsed, pkgName, cover, passStr, failStr, skipStr}
			line2 := []string{"", "", pkg.NoTestMessage, "", "", "", ""}
			allRows = append(allRows, RowLines{Lines: [][]string{line1, line2}})
			for i, cell := range line1 {
				if utf8.RuneCountInString(cell) > maxVals[i] {
					maxVals[i] = utf8.RuneCountInString(cell)
				}
			}
