func renderTestTablePlain(w io.Writer, tests []*Test, color bool, smallscreen bool) {
	headers := []string{"Status", "Elapsed", "Test", "Package"}
	type Row struct {
		Status    string
		Elapsed   string
		TestLines []string
		Package   string
	}
	var rows []Row
	for _, t := range tests {
		rows = append(rows, Row{
			Status:    t.Status,
			Elapsed:   formatElapsedTest(t.Elapsed),
			TestLines: splitTestNameSmallscreen(t.Name),
			Package:   t.Package,
		})
	}
	maxVals := []int{len(headers[0]), len(headers[1]), len(headers[2]), len(headers[3])}
	for _, r := range rows {
		if len(r.Status) > maxVals[0] {
			maxVals[0] = len(r.Status)
		}
		if len(r.Elapsed) > maxVals[1] {
			maxVals[1] = len(r.Elapsed)
		}
		for _, tl := range r.TestLines {
			if utf8.RuneCountInString(tl) > maxVals[2] {
				maxVals[2] = utf8.RuneCountInString(tl)
			}
		}
		if utf8.RuneCountInString(r.Package) > maxVals[3] {
			maxVals[3] = utf8.RuneCountInString(r.Package)
		}
	}
	widths := make([]int, 4)
	for i, mv := range maxVals {
		widths[i] = mv + 2
	}
	totalWidth := 0
	for _, wd := range widths {
		totalWidth += wd
	}
	totalWidth += len(widths) + 1 // spaces as separators (numCols+1)
	// Header
	fmt.Fprint(w, "  ")
	for i, h := range headers {
		fmt.Fprint(w, padCenter(h, widths[i]))
		if i < len(headers)-1 {
			fmt.Fprint(w, "  ")
		}
	}
	fmt.Fprint(w, "  \n")
	// separator line: spaces
	fmt.Fprintln(w, strings.Repeat(" ", totalWidth))
	for _, r := range rows {
